        string phase=couple?"career-fresh-couple-audit":relic?"career-fresh-relic-audit":tournaments?"career-fresh-tournaments-audit":purple?"career-fresh-purple-audit":snow?"career-fresh-snow-audit":flame?"career-fresh-flame-audit":beast?"career-fresh-beast-audit":ancient?"career-fresh-ancient-audit":equipment?"career-fresh-equipment-audit":"career-fresh-achievement-audit";
        if(couple){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint contributorUid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(contributorUid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Revora.Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);
var peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe WHERE done")),"FreshWar1");Revora.Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(FreshCoupleSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_couple_probe WHERE step=4")));}
        if(relic){
