        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint contributorUid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(contributorUid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Revora.Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);
Require(FreshRelicSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_relic_probe WHERE done")));}
        if(tournaments){var p=FreshLoadSaved(true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint contributorUid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(contributorUid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();var peer=players[3];Revora.Server.GamePool=players;Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w) && !w.Entity.Dead));


Require(FreshTeamArenaSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_team_twenty_probe WHERE stage=2 AND wins=20")));}
        if(purple){var p=FreshLoadSaved(true,true,true);Revora.Database.EntityVariableTable.Load(p);Revora.Database.SubClassTable.Load(p.Entity);Revora.Database.ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);Revora.Network.GamePackets.WayofHeroes.Load(p);Require(FreshPurpleCombatSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_purple_probe WHERE stage=4")));}
        if(snow){var p=FreshLoadSaved(true,true,true);Revora.Database.EntityVariableTable.Load(p);Revora.Database.SubClassTable.Load(p.Entity);Revora.Database.ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);Revora.Network.GamePackets.WayofHeroes.Load(p);Require(FreshSnowSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_snow_probe WHERE stage=3")));}
        if(flame){var p=FreshLoadSaved(true,true,true);Revora.Database.EntityVariableTable.Load(p);Revora.Database.SubClassTable.Load(p.Entity);Revora.Database.ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);Revora.Network.GamePackets.WayofHeroes.Load(p);Require(FreshFlameSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_flame_probe WHERE done")));}
        if(beast){var p=FreshLoadSaved(true,true,true);Revora.Database.EntityVariableTable.Load(p);Revora.Database.SubClassTable.Load(p.Entity);Revora.Database.ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);Revora.Network.GamePackets.WayofHeroes.Load(p);Require(FreshBeastSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_beast_probe WHERE step=2")));var bank=p.Warehouses[Revora.Game.ConquerStructures.Warehouse.WarehouseID.ApeCity];Require(bank!=null && (long)Sql("SELECT count(*) FROM items WHERE entityid=@uid AND warehouse=10028","uid",(long)p.Entity.UID)==bank.Count);}
        if(ancient){var p=FreshLoadSaved(true,true);Revora.Database.EntityVariableTable.Load(p);Revora.Database.SubClassTable.Load(p.Entity);Revora.Database.ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);Revora.Network.GamePackets.WayofHeroes.Load(p);Require(FreshAncientBossSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_ancient_boss_probe WHERE stage='claimed'")));}
