        long uid=Convert.ToInt64(Sql("SELECT uid FROM revora_fresh_starter_probe"));Require(uid==1096322);
        string snapshot=Convert.ToString(Sql(couple?"SELECT snapshot FROM revora_fresh_couple_probe WHERE step=4":relic?"SELECT snapshot FROM revora_fresh_relic_probe WHERE done":tournaments?"SELECT snapshot FROM revora_fresh_team_twenty_probe WHERE stage=2 AND wins=20":purple?"SELECT snapshot FROM revora_fresh_purple_probe WHERE stage=4":snow?"SELECT snapshot FROM revora_fresh_snow_probe WHERE stage=3":flame?"SELECT snapshot FROM revora_fresh_flame_probe WHERE done":beast?"SELECT snapshot FROM revora_fresh_beast_probe WHERE step=2":ancient?"SELECT snapshot FROM revora_fresh_ancient_boss_probe WHERE stage='claimed'":equipment?"SELECT snapshot FROM revora_fresh_equipment_packs_probe WHERE stage='opened'":"SELECT snapshot FROM revora_fresh_daily_claim_probe WHERE stage='used'"));Require(!string.IsNullOrEmpty(snapshot));string hash;
        using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(snapshot))).Replace("-","").ToLowerInvariant();
        string export=Convert.ToString(Sql(@"SELECT json_build_object('scope','Private fresh career receipt audit; presence is not independent proof of every achievement','checkpoint',@checkpoint,'snapshot_sha256',@hash,
