'receipts',(SELECT COALESCE(json_agg(r ORDER BY achievement_id),'[]'::json) FROM (SELECT achievement_id,source FROM revora_achievement_evidence WHERE uid=@uid) r))::text","uid",uid,"hash",hash,"checkpoint",checkpoint));
        File.WriteAllText(couple?"fresh-couple-achievement-audit.json":relic?"fresh-relic-achievement-audit.json":tournaments?"fresh-tournaments-achievement-audit.json":purple?"fresh-purple-achievement-audit.json":snow?"fresh-snow-achievement-audit.json":flame?"fresh-flame-achievement-audit.json":beast?"fresh-beast-achievement-audit.json":ancient?"fresh-ancient-achievement-audit.json":equipment?"fresh-equipment-achievement-audit.json":"fresh-achievement-audit.json",export,new UTF8Encoding(false));
        Require(snapshot==Convert.ToString(Sql(couple?"SELECT snapshot FROM revora_fresh_couple_probe WHERE step=4":relic?"SELECT snapshot FROM revora_fresh_relic_probe WHERE done":tournaments?"SELECT snapshot FROM revora_fresh_team_twenty_probe WHERE stage=2 AND wins=20":purple?"SELECT snapshot FROM revora_fresh_purple_probe WHERE stage=4":snow?"SELECT snapshot FROM revora_fresh_snow_probe WHERE stage=3":flame?"SELECT snapshot FROM revora_fresh_flame_probe WHERE done":beast?"SELECT snapshot FROM revora_fresh_beast_probe WHERE step=2":ancient?"SELECT snapshot FROM revora_fresh_ancient_boss_probe WHERE stage='claimed'":equipment?"SELECT snapshot FROM revora_fresh_equipment_packs_probe WHERE stage='opened'":"SELECT snapshot FROM revora_fresh_daily_claim_probe WHERE stage='used'")));
